'use strict';
const assert=require('node:assert/strict'),F=require('../fixtures'),{create}=require('../demo-core'),source=require('../store-source.json');
let groups=0;const test=(name,fn)=>{fn();groups++;console.log('PASS '+name);};
const bj=F.stores.filter(s=>s.city==='北京');
test('default catalog has exactly thirty unique Beijing stores',()=>{assert.equal(F.defaultCity,'北京');assert.equal(bj.length,30);assert.equal(new Set(bj.map(s=>s.id)).size,30);assert.equal(new Set(bj.map(s=>s.address)).size,30);});
test('all thirty Beijing sources have explicit workbook row mappings',()=>{for(const s of bj){const x=source.selected_stores.find(r=>r.id===s.id);assert(x&&x.row>1&&x.city==='北京市');assert.equal(s.name,x.name);assert.equal(s.source_address,x.address);}assert.equal(source.beijing_selected,30);});
test('sample spans eight normalized Beijing districts',()=>{assert.equal(new Set(source.selected_stores.filter(x=>x.city==='北京市').map(x=>x.district.replace(/^北京市?/,''))).size,8);});
test('every Beijing store has a configured and dimensionally consistent warehouse catalog',()=>{for(const s of bj){const rows=F.units.filter(u=>u.store_id===s.id);assert(rows.length>=3);for(const u of rows)assert(Math.abs(u.dimensions_m.reduce((a,b)=>a*b,1)-u.volume)<1e-7);}assert.equal(F.units.filter(u=>bj.some(s=>s.id===u.store_id)).length,120);});
test('sample covers available sold reserved occupied unavailable and paused states',()=>{const states=new Set(F.units.filter(u=>u.store_id.startsWith('SIM_BJ')).map(u=>u.status));for(const x of ['available','soldout','reserved','occupied','unavailable'])assert(states.has(x));assert(bj.some(s=>s.status==='closed'));});
test('full store profiles cannot be selected or recommended as available',()=>{const c=create();c.setScenario('normal');for(const sid of ['SIM_BJ05','SIM_BJ06','SIM_BJ07','SIM_BJ08','SIM_BJ09','SIM_BJ29']){assert.equal(c.matchingUnits(sid).length,0);for(const u of F.units.filter(x=>x.store_id===sid)){assert.equal(c.available(u),false);assert.throws(()=>c.select([u.id]),/UNAVAILABLE/);}}assert(c.alternatives().every(u=>c.available(u)));});
test('no-match recovery preserves demand under the expanded catalog',()=>{const c=create();c.setScenario('noMatch');assert.equal(c.matchingUnits().length,0);for(const s of bj)assert.equal(c.combinations(s.id).length,0);assert.equal(c.state().requirement.capacity_m3,200);assert.equal(c.state().requirement.term_months,6);});
test('catalog has no asserted coordinates and invalidates prior eight-store state',()=>{assert.equal(F.distanceVerified,false);assert(bj.every(s=>s.latitude===undefined&&s.longitude===undefined));const c=create({state:{schema:1,fixtureVersion:'STORE_FIXTURE_02_20261025',city:'上海'}});assert.equal(c.state().city,'北京');assert.equal(c.state().storeId,null);});
console.log(JSON.stringify({groups,beijing:bj.length,units:F.units.length,result:'PASS'}));
